INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Wird die Subnetzgrenze immer in Hexadezimal gezählt?', 2, '[{"text": "Ja", "correct": true, "because": "IPv6-Adressen sind hexadezimal"}, {"text": "Nein", "correct": false, "because": "Standardformat"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie lautet die nächste Subnetzgrenze nach 2001:db8:1::/64?', 3, '[{"text": "2001:db8:2::/64", "correct": true, "because": "Inkrement um 1 im 4. Block"}, {"text": "2001:db8:1:1::/64", "correct": false, "because": "Innerhalb desselben Subnetzes"}, {"text": "2001:db9::/64", "correct": false, "because": "Falscher Block"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Block erhöhe ich bei /64-Subnetzen in Hexadezimal?', 4, '[{"text": "4. Block", "correct": true, "because": "Erste 64 Bits, 4. Block inkrementiert"}, {"text": "3. Block", "correct": false, "because": "Teil des Netzwerkpräfixes"}, {"text": "5. Block", "correct": false, "because": "Interface-ID"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2001:db8:1::/64 bis 2001:db8:1:ffff::/64 ist ein Subnetz. b) Grenzen zählen in Hex.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) falsch, Grenze ist 2001:db8:2::"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist ungenau"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Berechnung von Subnetzgrenzen?', 5, '[{"text": "Einzelne Hostadressen", "correct": true, "because": "Nur Netzwerkgrenze zählt"}, {"text": "Hexadezimalzählung", "correct": false, "because": "Basis der Grenzen"}, {"text": "Präfixlänge", "correct": false, "because": "Definiert Grenze"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2001:db8:2::/64 nach 2001:db8:1::/64 kommt?', 2, '[{"text": "Ja", "correct": true, "because": "Hexadezimal inkrementiert"}, {"text": "Nein", "correct": false, "because": "Logische Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Grenze folgt auf 2001:db8:a::/64?', 3, '[{"text": "2001:db8:b::/64", "correct": true, "because": "Hex a zu b"}, {"text": "2001:db8:a:1::/64", "correct": false, "because": "Innerhalb desselben"}, {"text": "2001:db8:f::/64", "correct": false, "because": "Falscher Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren bestimmen Subnetzgrenzen?', 5, '[{"text": "Präfixlänge", "correct": true, "because": "Definiert Subnetzgröße"}, {"text": "Hexadezimalzählung", "correct": true, "because": "Inkrementiert Grenzen"}, {"text": "Hostanzahl", "correct": false, "because": "Nur Interface-ID"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Grenzen bei /64 zählen im 4. Block. b) Sie sind dezimal. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, hexadezimal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Subnetzgrenzen?', 4, '[{"text": "Präfix", "correct": false, "because": "Definiert Grenze"}, {"text": "Hex-Zählung", "correct": false, "because": "Bestimmt nächste Grenze"}, {"text": "Bandbreite", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 2001:db8:10::/64 die 16. Grenze nach 2001:db8::/64?', 2, '[{"text": "Ja", "correct": true, "because": "Hex 0 zu 10 ist 16"}, {"text": "Nein", "correct": false, "because": "Hexadezimal korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Grenzen definieren ein /64-Subnetz?', 4, '[{"text": "Start: 2001:db8:1::", "correct": true, "because": "Beginn des Bereichs"}, {"text": "Ende: 2001:db8:1:ffff:ffff:ffff:ffff", "correct": true, "because": "Letzte Adresse"}, {"text": "2001:db8:2::", "correct": false, "because": "Nächstes Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 2001:db8:1::/64 bis 2001:db8:2::/64 ein Subnetz ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Zwei separate Subnetze"}, {"text": "Ja", "correct": false, "because": "Falsche Grenze"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Subnetzgrenzen?', 3, '[{"text": "Hexadezimalzählung", "correct": true, "because": "Bestimmt nächste Grenze"}, {"text": "Hostadressen", "correct": false, "because": "Sekundär"}, {"text": "Kürzungsregeln", "correct": false, "because": "Darstellungssache"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Grenzen bei /48 zählen im 3. Block. b) /64 im 4. Block.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) 48 Bits, b) 64 Bits"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Grenzen erwartest du bei diesen Werten?', 5, '[{"text": "2001:db8:1::/64 zu 2001:db8:2::/64", "correct": true, "because": "Nächstes Subnetz"}, {"text": "2001:db8:a::/64 zu 2001:db8:b::/64", "correct": true, "because": "Hex-Schritt"}, {"text": "2001:db8:1::/64 zu 2001:db8:1:1::/64", "correct": false, "because": "Dasselbe Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Subnetzgrenzen unwichtig?', 3, '[{"text": "Präfixlänge", "correct": false, "because": "Definiert Grenze"}, {"text": "Hexadezimalzählung", "correct": false, "because": "Bestimmt Schritt"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 2001:db8:f::/64 vor 2001:db8:10::/64?', 2, '[{"text": "Ja", "correct": true, "because": "Hex f < 10"}, {"text": "Nein", "correct": false, "because": "Hexadezimal korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2001:db8:1fff::/64 die 8192. Grenze nach 2001:db8::/64 ist?', 3, '[{"text": "Ja", "correct": true, "because": "Hex 1fff = 8191 + 1"}, {"text": "Nein", "correct": false, "because": "Hexadezimal passt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Grenze liegt vor 2001:db8:5::/64?', 4, '[{"text": "2001:db8:4::/64", "correct": true, "because": "Hex 5 - 1 = 4"}, {"text": "2001:db8:5:0::/64", "correct": false, "because": "Dasselbe Subnetz"}, {"text": "2001:db8:6::/64", "correct": false, "because": "Falsche Richtung"}]');
